package prog

import (
	"fmt"
	"path"
	"slices"
	"strings"
)

// CallTemplate is a named ordered list of syscall selectors.
//
// Selectors are exact syscall names, shell patterns accepted by path.Match,
// or prefixes ending with '*'. Templates describe high-value sequences such as
// open-device/create-resource/operate; resource creation calls required by the
// selected calls are still generated by the normal argument generator.
type CallTemplate struct {
	Name      string   `json:"name"`
	Selectors []string `json:"selectors"`
	Weight    int      `json:"weight,omitempty"`
}

// CompiledCallTemplate is a CallTemplate resolved for one Target.
type CompiledCallTemplate struct {
	Name   string
	Calls  []*Syscall
	Weight int
}

// CompileCallTemplates resolves template selectors against the target.
// Disabled and no_generate calls are not valid template entry points.
func (target *Target) CompileCallTemplates(templates []CallTemplate) ([]*CompiledCallTemplate, error) {
	var compiled []*CompiledCallTemplate
	for _, tmpl := range templates {
		if len(tmpl.Selectors) == 0 {
			return nil, fmt.Errorf("call template %q has no selectors", tmpl.Name)
		}
		out := &CompiledCallTemplate{Name: tmpl.Name, Weight: tmpl.Weight}
		for _, selector := range tmpl.Selectors {
			meta, err := target.resolveTemplateCall(selector)
			if err != nil {
				return nil, fmt.Errorf("template %q: %w", tmpl.Name, err)
			}
			out.Calls = append(out.Calls, meta)
		}
		compiled = append(compiled, out)
	}
	return compiled, nil
}

// MustCompileCallTemplates is like CompileCallTemplates and panics on error.
// It is intended for static built-in templates and tests.
func (target *Target) MustCompileCallTemplates(templates []CallTemplate) []*CompiledCallTemplate {
	compiled, err := target.CompileCallTemplates(templates)
	if err != nil {
		panic(err)
	}
	return compiled
}

func (target *Target) resolveTemplateCall(selector string) (*Syscall, error) {
	if meta := target.SyscallMap[selector]; meta != nil {
		return usableTemplateCall(meta, selector)
	}
	var matches []*Syscall
	prefix := ""
	if strings.HasSuffix(selector, "*") {
		prefix = strings.TrimSuffix(selector, "*")
	}
	for _, meta := range target.Syscalls {
		ok, err := path.Match(selector, meta.Name)
		if err != nil {
			return nil, fmt.Errorf("bad call selector %q: %w", selector, err)
		}
		if !ok && prefix != "" {
			ok = strings.HasPrefix(meta.Name, prefix)
		}
		if ok && !meta.Attrs.Disabled && !meta.Attrs.NoGenerate {
			matches = append(matches, meta)
		}
	}
	if len(matches) == 0 {
		return nil, fmt.Errorf("no generatable syscall matches selector %q", selector)
	}
	slices.SortFunc(matches, func(a, b *Syscall) int { return a.ID - b.ID })
	return matches[0], nil
}

func usableTemplateCall(meta *Syscall, selector string) (*Syscall, error) {
	if meta.Attrs.Disabled {
		return nil, fmt.Errorf("syscall %q is disabled", selector)
	}
	if meta.Attrs.NoGenerate {
		return nil, fmt.Errorf("syscall %q is no_generate", selector)
	}
	return meta, nil
}
